head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil16650";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16650.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_division_onclick
 * @description rd_division 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_division_onclick = function(e){
    try {
        scwin.search(01)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16650.rd_division_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @param {*} num num
 * @returns {void}
 * @hidden N
 */
scwin.search = function (num) {
    if (num === '01') {
        ($c.util.getComponent("listing01") && $c.util.getComponent("listing01").show ? $c.util.getComponent("listing01").show() : console.warn('[sdd] show 대상 미해결: ' + "listing01"));
        ($c.util.getComponent("listing02") && $c.util.getComponent("listing02").hide ? $c.util.getComponent("listing02").hide() : console.warn('[sdd] hide 대상 미해결: ' + "listing02"));
    } else {
        ($c.util.getComponent("listing01") && $c.util.getComponent("listing01").hide ? $c.util.getComponent("listing01").hide() : console.warn('[sdd] hide 대상 미해결: ' + "listing01"));
        ($c.util.getComponent("listing02") && $c.util.getComponent("listing02").show ? $c.util.getComponent("listing02").show() : console.warn('[sdd] show 대상 미해결: ' + "listing02"));
    }
};
